  (fuel_2 : ℕ),
  BfgsVerification.DeterministicLineSearch.search F x p g c₁ c₂ fuel_2.succ l h a =
    if BfgsVerification.DeterministicLineSearch.Armijo F x p g c₁ a then
      if BfgsVerification.DeterministicLineSearch.Wolfe F x p g c₂ a then (some a, [a])
      else
        let r :=
          BfgsVerification.DeterministicLineSearch.search F x p g c₁ c₂ fuel_2 a h
            (BfgsVerification.DeterministicLineSearch.nextTrial a h);
        (r.1, a :: r.2)
    else
      let r :=
        BfgsVerification.DeterministicLineSearch.search F x p g c₁ c₂ fuel_2 l (some a)
          (BfgsVerification.DeterministicLineSearch.nextTrial l (some a));
      (r.1, a :: r.2)

