  {scale_pos : ∀ (m : ℕ), 0 < BfgsVerification.LNormalizedReturn.scale (state m)}
  {conditions : ∀ (m : ℕ), BfgsVerification.LNormalizedOracle.Conditions μ c₁ c₂ (state m)}
  {next : ∀ (m : ℕ), state (m + 1) = BfgsVerification.LNormalizedReturn.returnMap μ (state m)}
  {state_1 : ℕ → BfgsVerification.LNormalizedReturn.State}
  {scale_pos_1 : ∀ (m : ℕ), 0 < BfgsVerification.LNormalizedReturn.scale (state_1 m)}
  {conditions_1 : ∀ (m : ℕ), BfgsVerification.LNormalizedOracle.Conditions μ c₁ c₂ (state_1 m)}
  {next_1 : ∀ (m : ℕ), state_1 (m + 1) = BfgsVerification.LNormalizedReturn.returnMap μ (state_1 m)},
  { state := state, scale_pos := scale_pos, conditions := conditions, next := next } =
      { state := state_1, scale_pos := scale_pos_1, conditions := conditions_1, next := next_1 } →
    state = state_1

∀ {n : ℕ} (A : BfgsVerification.Mat n) (hA : Matrix.det A ≠ 0) {F : BfgsVerification.Vec n → ℝ}
  (R : BfgsVerification.AdmissibleBFGSRun n F) (k : ℕ),
  (BfgsVerification.AffineWhitening.run A hA R).x k = BfgsVerification.AffineWhitening.point A (R.x k)

∀ {n : ℕ} {Q F : BfgsVerification.Vec n → ℝ} {c : BfgsVerification.Vec n} {C : ℝ} {U : Set (BfgsVerification.Vec n)}
  (D : BfgsVerification.ScaledCopy.Data Q F c C U) (R : BfgsVerification.AdmissibleBFGSRun n Q)
  (hx : ∀ (k : ℕ), R.x k ∈ U) (m k : ℕ), (D.run R hx m).H k = R.H k

∀ {n : ℕ} {ι : Type u_1} [inst : Fintype ι] {m : ι → ℕ}
  (A : (i : ι) → BfgsVerification.Vec n →L[ℝ] EuclideanSpace ℝ (Fin (m i))) (b : (i : ι) → EuclideanSpace ℝ (Fin (m i)))
  (star z : BfgsVerification.Vec n), 0 ≤ BfgsVerification.EuclideanResidual.centeredGauge A b star z

∀ {F : BfgsVerification.Vec 2 → ℝ} {c : BfgsVerification.Vec 2} {f : Fin 2 → BfgsVerification.Vec 2 → ℝ}
  {W : BfgsVerification.Vec 2 → BfgsVerification.Vec 2}
  (self : BfgsVerification.PlanarCrossing.CornerSecantData F c f W) (i : Fin 2),
  ∀ x ∈ Metric.closedBall c self.radius, ‖BfgsVerification.coordinateGradient (f i) x‖ ≤ self.H

∀ {n : ℕ} {F : BfgsVerification.Vec n → ℝ} {R : BfgsVerification.AdmissibleBFGSRun n F}
  (self : BfgsVerification.ResidualFrameCertificate R) (k : ℕ),
  BfgsVerification.SmoothSubspace.frobSq (self.Z k) ≤ self.C_R * (R.shift self.J).d k

∀ {X : Type u_3} [inst : NormedAddCommGroup X] [inst_1 : NormedSpace ℝ X] (F : X →L[ℝ] X),
  BfgsVerification.AnalyticStableGraph.linearStableSet F =
    {v | Filter.Tendsto (fun n => (F ^ n) v) Filter.atTop (nhds 0)}

∀ {n : ℕ} (H : BfgsVerification.Mat n) (g y : BfgsVerification.Vec n) (α : ℝ),
  α ≠ 0 →
    BfgsVerification.metricEnergy H g ≠ 0 →
      -BfgsVerification.dot y (Matrix.mulVec H g) / BfgsVerification.metricEnergy H g ≠ 0 →
        let q := BfgsVerification.metricEnergy H g;
        let β := -BfgsVerification.dot y (Matrix.mulVec H g) / q;
        let v := Matrix.mulVec H g;
        BfgsVerification.inverseBFGS H (BfgsVerification.bfgsStep H g α) y =
          (1 + (β * q)⁻¹ • BfgsVerification.outer v y) * H * (1 + (β * q)⁻¹ • BfgsVerification.outer y v) +
            (α / (β * q)) • BfgsVerification.outer v v

∀ {F : BfgsVerification.Vec 2 → ℝ} {c : BfgsVerification.Vec 2} {f : Fin 2 → BfgsVerification.Vec 2 → ℝ}
  {W : BfgsVerification.Vec 2 → BfgsVerification.Vec 2}
  (self : BfgsVerification.PlanarCrossing.CornerSecantData F c f W), 0 < self.radius

∀ {f g : BfgsVerification.LNormalizedReturn.State → BfgsVerification.Mat 2}
  {w : BfgsVerification.LNormalizedReturn.State},
  AnalyticAt ℝ f w → AnalyticAt ℝ g w → AnalyticAt ℝ (fun z => f z * g z) w
